SELECT TR.TEST_NO , TR.TITLE , TR.CONTENT , TR.REQ_RMRK , TR.REQ_DATE , TR.REQ_ID , U.USER_NAME , TR.CREATE_DATE , TR.CREATE_USER_ID , TR.MODIFY_DATE , TR.MODIFY_USER_ID FROM TEST_REQUEST TR LEFT JOIN USERS U ON U.USER_ID = TR.REQ_ID WHERE TR.STATUS IN ('의뢰', '수정')
AND U.USER_NAME = #{userName}
AND TR.TITLE LIKE LIKE '%' || #{title} || '%'
AND TR.REQ_DATE >= #{reqStrDate}
AND TR.REQ_DATE <= #{reqEndDate}

